// Minimal HTML tokenizer + tree builder.
//
// No DOM library is shipped with this server, and `DOMParser` does not exist in
// a Bun process, so the crawler parses markup with its own small scanner. The
// grammar is deliberately forgiving — real pages are hand-edited by humans,
// generated by five different template engines, and full of `<br/>`s without
// closing tags. Anything that does not parse is dropped, never thrown.
//
// The node type is the whole contract between this module and the others:
//   { tag: string, attrs: Map<string,string>, children: Node[], text: string }

export type Node =
  | { tag: "text"; text: string }
  | { tag: string; attrs: Map<string, string>; children: Node[]; text: string };

const VOID = new Set([
  "area",
  "base",
  "br",
  "col",
  "embed",
  "hr",
  "img",
  "input",
  "link",
  "meta",
  "param",
  "source",
  "track",
  "wbr",
]);

/** Elements that browsers implicitly close when their own opening tag appears. */
const IMPLICIT_CLOSE = new Set(["p", "li", "dt", "dd", "h1", "h2", "h3", "h4", "h5", "h6", "tr", "th", "td", "body", "div"]);

function isWhiteSpace(ch: string): boolean {
  return ch === " " || ch === "\t" || ch === "\n" || ch === "\r";
}

function isNameStart(ch: string): boolean {
  return (ch >= "a" && ch <= "z") || (ch >= "A" && ch <= "Z") || ch === "_" || ch === ":" || ch === "-" || ch === "." || ch >= "\u0080";
}

function isNameChar(ch: string): boolean {
  return isNameStart(ch) || (ch >= "0" && ch <= "9");
}

/**
 * Decode the five named HTML entities plus numeric ones. Attributes and text
 * travel through here; the markup itself is left untouched so the tree keeps
 * whatever whitespace the browser kept.
 */
export function decodeEntities(escaped: string): string {
  return escaped
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCodePoint(Number.parseInt(hex, 16)))
    .replace(/&#([0-9]+);/g, (_, dec) => String.fromCodePoint(Number.parseInt(dec, 10)))
    .replace(/&#x([0-9a-fA-F]+)/g, (_, hex) => String.fromCodePoint(Number.parseInt(hex, 16)));
}

/** Split `&entities;` from surrounding text, leaving the entities for decode. */
function splitEntities(input: string): { text: string; entity: string }[] {
  const out: { text: string; entity: string }[] = [];
  let rest = input;
  let index = 0;
  const entityRe = /&(?:#[0-9]+|&[a-zA-Z0-9]+;)/g;
  let match: RegExpExecArray | null;
  while ((match = entityRe.exec(rest)) !== null) {
    out.push({ text: rest.slice(0, match.index), entity: match[0] });
    rest = rest.slice(match.index + match[0].length);
  }
  out.push({ text: rest, entity: "" });
  return out;
}

/**
 * Tokenize markup into an array of chunks: text (with entities decoded) or an
 * opening/closing tag object. Malformed fragments are retained as text rather
 * than dropped, so a page that uses `<img src=x` without a close bracket loses
 * the image instead of crashing the crawl.
 */
export function tokenize(html: string): Array<{ type: "text"; value: string } | { type: "tag"; value: string; closing: boolean }> {
  const out: Array<{ type: "text"; value: string } | { type: "tag"; value: string; closing: boolean }> = [];
  let rest = html;

  while (rest.length > 0) {
    const open = rest.search(/<[a-zA-Z\/]/);
    if (open === -1) {
      out.push({ type: "text", value: rest });
      break;
    }
    if (open > 0) {
      out.push({ type: "text", value: rest.slice(0, open) });
      rest = rest.slice(open);
    }

    const next = rest[0] === "<" ? rest.slice(1) : "";
    const match = /^<([a-zA-Z][a-zA-Z0-9:_.-]*)([^>]*)>/.exec(next);
    if (!match) {
      // No well-formed tag: treat the whole `<...` as text.
      out.push({ type: "text", value: "<" + next });
      rest = next.slice((match ? next.indexOf(">") : 0) + 1);
      continue;
    }

    const tagName = match[1].toLowerCase();
    const inner = match[2] || "";
    const isClosing = inner.startsWith("/");
    const restOfTag = isClosing ? inner.slice(1).trimStart() : inner.trimStart();

    // Attributes: keep the raw string so we can decode entities later.
    const attrRe = /([a-zA-Z_:][a-zA-Z0-9_:.-]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))/g;
    const attrs = new Map<string, string>();
    let attrMatch: RegExpExecArray | null;
    attrRe.lastIndex = 0;
    while ((attrMatch = attrRe.exec(restOfTag)) !== null) {
      const raw = attrMatch[2] !== undefined ? attrMatch[2] : attrMatch[3] !== undefined ? attrMatch[3] : attrMatch[4] ?? "";
      attrs.set(attrMatch[1].toLowerCase(), decodeEntities(raw));
    }

    if (VOID.has(tagName) || restOfTag.endsWith("/")) {
      out.push({ type: "tag", value: `<${tagName}${restOfTag.endsWith("/") ? "" : " "}${restOfTag.replace(/\/$/, "")}>`, closing: false });
      rest = rest.slice(match[0].length);
      continue;
    }

    const end = rest.indexOf("</" + tagName + ">", match[0].length);
    if (end === -1) {
      // Never silently swallow an unclosed tag: feed it to the consumer as
      // plain text so the page still renders.
      out.push({ type: "text", value: "<" + next.slice(match[0].length - 1) });
      rest = rest.slice(match[0].length);
      continue;
    }
    out.push({ type: "tag", value: next.slice(0, match[0].length + end), closing: false });
    out.push({ type: "tag", value: "</" + tagName + ">", closing: true });
    rest = rest.slice(end + (tagName.length + 3));
  }

  return out;
}

/** Build one node at a time. Returns the completed node and the remaining tokens. */
function buildNode(tokens: Array<{ type: "text"; value: string } | { type: "tag"; value: string; closing: boolean }>, start: number): {
  node: Node;
  next: number;
} {
  const node: Node = { tag: "text", attrs: new Map(), children: [], text: "" };

  for (let i = start; i < tokens.length; i++) {
    const token = tokens[i];
    if (token.type === "text") {
      node.text += token.value;
      continue;
    }
    if (token.closing) {
      // The matching closer finished this node.
      return { node, next: i + 1 };
    }

    const tagRe = /^<([a-zA-Z][a-zA-Z0-9:_.-]*)([^>]*)>/.exec(token.value);
    if (!tagRe) {
      // Should not happen: a text token would have absorbed it.
      node.text += token.value;
      continue;
    }

    const tagName = tagRe[1].toLowerCase();
    const inner = tagRe[2] || "";
    const isClosing = inner.startsWith("/");
    const restOfTag = isClosing ? inner.slice(1).trimStart() : inner.trimStart();

    const attrs = new Map<string, string>();
    const attrRe = /([a-zA-Z_:][a-zA-Z0-9_:.-]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))/g;
    let attrMatch: RegExpExecArray | null;
    attrRe.lastIndex = 0;
    while ((attrMatch = attrRe.exec(restOfTag)) !== null) {
      const raw = attrMatch[2] !== undefined ? attrMatch[2] : attrMatch[3] !== undefined ? attrMatch[3] : attrMatch[4] ?? "";
      attrs.set(attrMatch[1].toLowerCase(), decodeEntities(raw));
    }

    if (VOID.has(tagName) || restOfTag.endsWith("/")) {
      node.children.push({ tag: tagName, attrs, children: [], text: "" });
      continue;
    }

    const close = tokens.indexOf(
      { type: "tag", value: "</" + tagName + ">", closing: true },
      i + 1,
    );
    if (close === -1) {
      // Missing closer is the most common real-world error. The parent's closer
      // wins, or the node is dropped — never an exception.
      node.children.push({ tag: tagName, attrs, children: [], text: "" });
      continue;
    }

    const child = buildNode(tokens, i + 1);
    node.children.push(child.node);
    i = child.next - 1;
  }

  return { node, next: tokens.length };
}

/** Parse markup into a node tree. `html` may be any fragment; the root is always a text node. */
export function parse(html: string): Node {
  if (typeof html !== "string") return { tag: "text", attrs: new Map(), children: [], text: "" };
  const tokens = tokenize(html);
  const { node, next } = buildNode(tokens, 0);
  return node;
}

/** True when the element is a head content element — invisible in the final markdown. */
export function isHeadTag(tag: string): boolean {
  return tag === "style" || tag === "script" || tag === "noscript" || tag === "template" || tag === "svg" || tag === "math";
}

/** An element is a layout object when its job is structure, not content. */
export function isLayoutTag(tag: string): boolean {
  return (
    tag === "nav" ||
    tag === "footer" ||
    tag === "aside" ||
    tag === "header" ||
    tag === "form" ||
    tag === "figure" ||
    tag === "dialog" ||
    tag === "audio" ||
    tag === "video" ||
    tag === "canvas" ||
    tag === "details" ||
    tag === "main"
  );
}

/**
 * Small predicate helper: `tag` matches exactly and every class/id in
 * `classes` matches a token of the element's `class` attribute.
 */
export function matches({ tag, attrs }: Node, tagOpt: string | null, classes: string[]): boolean {
  if (tagOpt !== null && tag !== tagOpt) return false;
  const classAttr = attrs.get("class") ?? "";
  const have = classAttr.split(/\s+/).filter(Boolean);
  return classes.every((c) => have.includes(c));
}

/** Return a map of lowercased attribute names to their decoded values. */
export function attrOf(node: Node, name: string): string | null {
  return node.attrs.get(name.toLowerCase()) ?? null;
}

/** Join the direct children's text, collapsed to a single line. */
export function textOf(node: Node): string {
  return node.children.map((c) => (c.tag === "text" ? c.text : textOf(c))).join("");
}
